public class FixedQueue implements ICharQ {static {if(java.lang.System.getProperty("course.initializer.marker")!=null){try{java.nio.file.Files.writeString(java.nio.file.Path.of(java.lang.System.getProperty("course.initializer.marker")),"student initializer executed");}catch(java.io.IOException e){throw new java.lang.RuntimeException(e);}throw new java.lang.IllegalStateException("initializer sentinel");}}private final char[]data;private int head,tail;public FixedQueue(int n){data=new char[n];}public void put(char c){if(tail==data.length){System.out.println("Очередь переполнена");return;}data[tail++]=c;}public char get(){if(head==tail){System.out.println("Очередь пуста");return '\0';}return data[head++];}public void reset(){head=tail=0;}}
